head.script:
scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof generator1 !== 'undefined') {
        generator1.remove();
    }

    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // Generator 컴포넌트의 자식인 Group 생성
    let grp_comp = $c.gcm.getTestGroup();

    let strGenerator = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strGenerator += '<w2:generator ' +strNameSpace+ ' id="generator1">';
    strGenerator += '<w2:editor id="generator1_child" style="width:500px; height:300px;" ev:onclick="scwin.generator1_child_onclick"></w2:editor>';
    strGenerator += '</w2:generator>';

    scwin.generator1 = await $p.dynamicCreate(
        "generator1",
        "generator",
        strGenerator,
        grp_comp
    );

    // Generator 자식이 아닌 standalone editor 를 먼저 await 생성 -> editor 비동기 라이브러리 로드 완료
    await $c.gcm.createBasicEditor('', 'ev:onclick="scwin.target1_onclick"');

    // editor 는 비동기 plugin 이므로 generator 자식 렌더링에 insertChildAsync 사용
    //  - 라이브러리 로드(위 createBasicEditor) 후 호출해야 generator 자식 editor 가 정상 렌더됨 (insertChild 또는 라이브러리 미로드 시 미렌더)
    await scwin.generator1.insertChildAsync(0);
}
